-- Tabla adicional: evita confundir valores del prototipo con fichas certificadas.
CREATE TABLE IF NOT EXISTS calidad_ficha_cultivo (
 id_cultivo INT NOT NULL PRIMARY KEY,
 estado VARCHAR(30) NOT NULL DEFAULT 'demostracion',
 fuente VARCHAR(180) NOT NULL DEFAULT 'Rangos iniciales orientativos; verificacion pendiente',
 fuente_url VARCHAR(500) DEFAULT NULL,
 observaciones VARCHAR(500) DEFAULT NULL,
 actualizado_en TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
 CONSTRAINT fk_calidad_ficha_cultivo FOREIGN KEY (id_cultivo) REFERENCES cultivos(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
INSERT INTO calidad_ficha_cultivo (id_cultivo,estado,fuente,observaciones)
SELECT c.id, 'demostracion', 'Estimacion inicial para probar AgroPlant',
       'Temperatura y precipitacion mensuales orientativas; pendiente de validacion local para variedad y zona.'
FROM cultivos c
WHERE c.slug IN (
'maiz','frijol','sorgo','avena','garbanzo','girasol','tomate','calabaza','chile','papa','cebada','camote','sandia','melon','pepino','zanahoria','cebolla','lechuga','arroz','trigo','centeno','mijo','quinoa','amaranto','cacahuate','lenteja','haba','chicharo','soya','alfalfa','trebol','canola','ajonjoli','algodon','cana_azucar','agave','nopal','yuca','betabel','rabano','brocoli','coliflor','repollo','espinaca','acelga','apio','ajo','poro','berenjena','chayote','ejote','tomatillo','jicama','fresa','frambuesa','zarzamora','arandano','platano','mango','papaya','pina','aguacate','limon','naranja','mandarina','toronja','manzana','pera','durazno','ciruela','guayaba','guanabana','coco','cafe','cacao','uva','granada','tamarindo','pitahaya','higo','chile_habanero','chile_jalapeno','esparrago','jamaica','stevia','cilantro','perejil','albahaca','romero','menta')
ON DUPLICATE KEY UPDATE id_cultivo=id_cultivo;

-- Fuentes de referencia para futuras validaciones (no atribuye estos 90 rangos a la FAO).
INSERT INTO fuentes (id,nombre,url,uso) VALUES
 ('FAO_ECOCROP','FAO ECOCROP','https://gaez.fao.org/pages/ecocrop','Validacion futura de rangos de temperatura y lluvia'),
 ('FAO_GAEZ','FAO GAEZ','https://gaez.fao.org/','Aptitud de cultivos y factores agroecologicos'),
 ('ECOSTRESS','NASA ECOSTRESS','https://ecostress.jpl.nasa.gov/data','Estres termico e hidrico'),
 ('SRTM','NASA SRTM','https://www.earthdata.nasa.gov/data/instruments/srtm','Elevacion, relieve y pendiente')
ON DUPLICATE KEY UPDATE nombre=VALUES(nombre),url=VALUES(url),uso=VALUES(uso);

-- ===============================================================
-- AUTOVERIFICACION: la segunda columna debe ser 0 para el catalogo inicial.
-- Si se han creado cultivos nuevos manualmente, pueden seguir sin ficha.
-- ===============================================================
SELECT COUNT(*) AS cultivos_registrados,
 SUM(CASE WHEN temp_min IS NULL OR temp_max IS NULL
 OR lluvia_mes_min IS NULL OR lluvia_mes_max IS NULL THEN 1 ELSE 0 END) AS cultivos_sin_parametros,
 SUM(CASE WHEN temp_min IS NOT NULL AND temp_max IS NOT NULL
 AND lluvia_mes_min IS NOT NULL AND lluvia_mes_max IS NOT NULL THEN 1 ELSE 0 END) AS cultivos_con_parametros
FROM cultivos;
SELECT (SELECT COUNT(*) FROM estados) AS estados,
 (SELECT COUNT(*) FROM imagenes_cultivo) AS enlaces_imagenes,
 (SELECT COUNT(*) FROM fuentes) AS fuentes_registradas,
 (SELECT COUNT(*) FROM calidad_ficha_cultivo) AS fichas_demo;
SELECT nombre,temp_min,temp_max,lluvia_mes_min,lluvia_mes_max,agua
FROM cultivos ORDER BY nombre LIMIT 25;
